  evaluation: [['Define population structure.', 'The make-up of a population by age, sex and other characteristics.'], ['Give one example of each group of components.', 'Demographic: age. Socio-political: religion. Economic: occupation.']],
  remediation: ['Males per 100 females is the ______ ratio.', 'Language and religion are ______ components.', 'Occupation is an ______ component.'], remediationAnswers: '1. sex 2. socio-political 3. economic',
  homework: 'Make a table of your family members by age, sex and occupation.', homeworkTag: 'This prepares Lesson 6: Age and Sex Composition.',
